'use client';

import React, { useState, useRef, useEffect } from 'react';
import WeatherCard from './WeatherCard';
import StockCard from './StockCard';

interface Message {
  role: string;
  content: string;
  timestamp?: string;
  components?: any[];
}

interface ChatInterfaceProps {
  messages: Message[];
  onSendMessage: (message: string) => void;
  isLoading: boolean;
  isDarkMode: boolean;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  messages,
  onSendMessage,
  isLoading,
  isDarkMode,
}) => {
  const [inputValue, setInputValue] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputValue.trim() && !isLoading) {
      onSendMessage(inputValue.trim());
      setInputValue('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  const adjustTextareaHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
    }
  };

  useEffect(() => {
    adjustTextareaHeight();
  }, [inputValue]);

  const renderMessage = (message: Message, index: number) => {
    const isUser = message.role === 'user';
    const isAssistant = message.role === 'assistant';

    return (
      <div
        key={index}
        className={`flex ${isUser ? 'justify-end' : 'justify-start'} mb-4`}
      >
        <div className={`flex gap-3 max-w-3xl ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
          {/* Avatar */}
          <div className={`
            w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-medium
            ${isUser ? 'bg-blue-600' : 'bg-gray-600 dark:bg-gray-500'}
          `}>
            {isUser ? 'U' : 'AI'}
          </div>

          {/* Message Content */}
          <div className={`
            rounded-lg px-4 py-3 max-w-full
            ${isUser 
              ? 'bg-blue-600 text-white' 
              : 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-100'
            }
          `}>
            <div className="prose prose-sm max-w-none">
              <p className="whitespace-pre-wrap break-words mb-0">
                {message.content}
              </p>
            </div>

            {/* Render Components */}
            {message.components && message.components.map((component, compIndex) => {
              if (component.type === 'weather') {
                return <WeatherCard key={compIndex} data={component} />;
              }
              if (component.type === 'stock') {
                return <StockCard key={compIndex} data={component} />;
              }
              return null;
            })}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-white dark:bg-gray-950">
      {/* Header */}
      <div className="border-b border-gray-200 dark:border-gray-700 p-4">
        <h1 className="text-xl font-semibold text-gray-800 dark:text-gray-200">
          ChatGPT Clone
        </h1>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Ask me anything! I can provide weather info and stock data.
        </p>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full">
            <div className="text-center max-w-md">
              <div className="text-4xl mb-4">💬</div>
              <h2 className="text-xl font-semibold text-gray-600 dark:text-gray-300 mb-2">
                Start a Conversation
              </h2>
              <p className="text-gray-500 dark:text-gray-400 mb-6">
                Ask me about weather, stocks, or anything else you'd like to know!
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
                <button
                  onClick={() => onSendMessage("What's the weather like in New York?")}
                  className="p-3 text-left bg-gray-50 dark:bg-gray-800 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                  disabled={isLoading}
                >
                  <div className="font-medium text-gray-700 dark:text-gray-300">
                    Weather Example
                  </div>
                  <div className="text-gray-500 dark:text-gray-400">
                    "What's the weather like in New York?"
                  </div>
                </button>
                <button
                  onClick={() => onSendMessage("Show me Apple stock price")}
                  className="p-3 text-left bg-gray-50 dark:bg-gray-800 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                  disabled={isLoading}
                >
                  <div className="font-medium text-gray-700 dark:text-gray-300">
                    Stock Example
                  </div>
                  <div className="text-gray-500 dark:text-gray-400">
                    "Show me Apple stock price"
                  </div>
                </button>
              </div>
            </div>
          </div>
        ) : (
          messages.map(renderMessage)
        )}

        {/* Loading Indicator */}
        {isLoading && (
          <div className="flex justify-start mb-4">
            <div className="flex gap-3 max-w-3xl">
              <div className="w-8 h-8 rounded-full bg-gray-600 dark:bg-gray-500 flex items-center justify-center text-white text-sm font-medium">
                AI
              </div>
              <div className="bg-gray-100 dark:bg-gray-800 rounded-lg px-4 py-3">
                <div className="flex items-center space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                </div>
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input Form */}
      <div className="border-t border-gray-200 dark:border-gray-700 p-4">
        <form onSubmit={handleSubmit} className="max-w-4xl mx-auto">
          <div className="flex gap-3 items-end">
            <div className="flex-1 relative">
              <textarea
                ref={textareaRef}
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Type your message..."
                className="w-full resize-none border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-3 
                         bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 
                         focus:ring-2 focus:ring-blue-500 focus:border-transparent
                         placeholder-gray-500 dark:placeholder-gray-400"
                rows={1}
                style={{ minHeight: '50px', maxHeight: '120px' }}
                disabled={isLoading}
              />
            </div>
            <button
              type="submit"
              disabled={!inputValue.trim() || isLoading}
              className="bg-blue-600 hover:bg-blue-700 disabled:bg-gray-300 disabled:dark:bg-gray-600 
                       text-white p-3 rounded-lg transition-colors flex items-center justify-center"
              title="Send message"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
              </svg>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ChatInterface; 